import json, os, re, subprocess, csv, datetime as dt
from pathlib import Path
from collections import defaultdict

DEV = Path(r"C:/Users/eric_rash/Desktop/DEV")
DRIVE = Path(r"G:/My Drive/00_Primary_Storage_Drive")
SKIP = {"_ARCHIVE", "_DRIVE", "_to_delete", "docs", "graphify-out", "_INBOX"}
today = dt.date(2026, 10, 3)

def norm(n):
    n = re.sub(r"^\d{4}(-\d{2}-\d{2})?_", "", n)
    n = re.sub(r"\.(docx|pdf|md)$", "", n, flags=re.I)
    return re.sub(r"[^a-z0-9]", "", n.lower())

def git(p, *a):
    try:
        return subprocess.run(["git", "-C", str(p), *a], capture_output=True, text=True, timeout=20).stdout.strip()
    except Exception:
        return ""

rows = {}
for d in sorted(DEV.iterdir()):
    if not d.is_dir() or d.name in SKIP or d.name.startswith("."):
        continue
    last = git(d, "log", "-1", "--format=%cs")
    dirty = len([l for l in git(d, "status", "--porcelain").splitlines() if l.strip()])
    remote = bool(git(d, "remote"))
    status = (d / "docs" / "STATUS.md").exists()
    age = (today - dt.date.fromisoformat(last)).days if last else None
    rows[d.name] = dict(name=d.name, key=norm(d.name), dev=True, last_commit=last, age_days=age,
                        dirty=dirty, remote=remote, status_md=status, registry="", drive="")

reg = json.load(open(DEV / "project-triage/portfolio.json", encoding="utf-8"))
regnames = {}
for sect in ("projects", "ideas", "inbox"):
    items = reg.get(sect, [])
    for it in items:
        if isinstance(it, dict):
            nm = it.get("name") or it.get("id") or it.get("title") or ""
            st = it.get("status") or it.get("stage") or sect
        else:
            nm, st = str(it), sect
        if nm:
            regnames[norm(nm)] = (nm, f"{sect}:{st}")

drive = {}
for stage in ("_ACTIVE", "_DONE", "_STALLED"):
    for f in (DRIVE / "01_PROJECTS" / stage).iterdir():
        drive.setdefault(norm(f.name), []).append(f"{stage}/{f.name}")

keys = {r["key"]: r for r in rows.values()}
for k, (nm, st) in regnames.items():
    if k in keys: keys[k]["registry"] = st
    else: rows["REG:" + nm] = dict(name=nm, key=k, dev=False, registry=st, drive="", last_commit="", age_days=None, dirty=0, remote=False, status_md=False)
for k, locs in drive.items():
    hit = [r for r in rows.values() if r["key"] == k]
    if hit: hit[0]["drive"] = "; ".join(locs)
    else: rows["DRV:" + k] = dict(name=locs[0], key=k, dev=False, registry="", drive="; ".join(locs), last_commit="", age_days=None, dirty=0, remote=False, status_md=False)

out = Path(r"C:/Users/eric_rash/.claude/jobs/754bb143/tmp/crosswalk.csv")
with open(out, "w", newline="", encoding="utf-8") as fh:
    w = csv.DictWriter(fh, fieldnames=list(next(iter(rows.values())).keys()))
    w.writeheader(); [w.writerow(r) for r in rows.values()]

dev = [r for r in rows.values() if r["dev"]]
print("DEV folders:", len(dev), "| in registry:", sum(1 for r in dev if r["registry"]), "| with Drive match:", sum(1 for r in dev if r["drive"]))
print("no remote:", [r["name"] for r in dev if not r["remote"]])
print("dirty>0:", sum(1 for r in dev if r["dirty"]), "| has STATUS.md:", sum(1 for r in dev if r["status_md"]))
buckets = defaultdict(int)
for r in dev:
    a = r["age_days"]
    b = "no commits" if a is None else "<=30d" if a <= 30 else "31-90d" if a <= 90 else ">90d"
    buckets[b] += 1
print("commit age:", dict(buckets))
print("unregistered & >60d idle:", len([r for r in dev if not r["registry"] and (r["age_days"] or 999) > 60]))
print("registry with no DEV folder:", [r["name"] for r in rows.values() if r["name"] and not r["dev"] and r["registry"]])
print("Drive projects with no DEV folder:", [r["name"] for r in rows.values() if not r["dev"] and r["drive"] and not r["registry"]])

# families by shared prefix token
fam = defaultdict(list)
for r in rows.values():
    tok = re.split(r"[_\-\s]", re.sub(r"^\d{4}(-\d{2}-\d{2})?_", "", r["name"]))[0].lower()
    tok = {"valdreport": "vald", "jumpreporting": "jump", "softwaretechdocs": "softwaretech", "cmj": "jump"}.get(tok, tok)
    if len(tok) >= 3: fam[tok].append(r["name"])
print("\nFAMILIES (>=2):")
for t, ms in sorted(fam.items(), key=lambda x: -len(x[1])):
    if len(ms) >= 2: print(f"  {t} ({len(ms)}): {', '.join(ms)}")

