import os, re, json, datetime as dt
from pathlib import Path
DEV = Path(r"C:/Users/eric_rash/Desktop/DEV")
FAM = {
 "VALD": ["VALD_analytics","VALD_Performance","VALD_Release","ValdReport"],
 "Jump/CMJ": ["cmj-norms-app","cmj-traffic-light","Jump_Dash","JumpReporting","shiny-vertical-jump","ForcePlate_DecisionSystem"],
 "RTP": ["RTP_Constraints_Course","RTP_DataCollection_Talk","RTP_ProgressReport","RTP_WorkingGroup","Non-Negative-Matrix-Factorization-RTP"],
 "SoftwareTech": ["SoftwareTech_Mgmt_Framework","SoftwareTech_Review","SoftwareTechDocs","Sport_Tech_Vetting","Tech_Inventory_Analysis"],
 "Education": ["Education_Alignment_Initiative","Education_Content_Agent","CPSS_BaylorSportScience_Curriculum","Intern_Curriculum","TechEd_Prop"],
 "Football": ["Football","Football_Data_DEV","Football_GRID","DataBase_GPS_Reporting","WeeklyCoachReport","CoachReport_Prototypes","PostGameReport"],
 "CFB": ["CFB_Analytics_Lab","CFB_Forecast_Archive","CFB_Victory_Model"],
 "Risk/Injury": ["Risk_Exposure_Windows","Risk_Stratification_Engine","InjurPred","Injury_Surveillance"],
 "Knowledge": ["Flint","SportScienceResearchRepo","ZoteroInjestion","LibraryProject","BookVaultApp","BookInbox","KnowledgeManagement","ContextVault","Weekly_Research_Review","Education_Content_Agent"],
 "Dashboards": ["CommandCentre","KeystoneOS","project-triage","Life-OS","AgentAssist","morning-briefing"],
}
SKIPD = {".git","node_modules",".venv","venv","__pycache__","renv",".Rproj.user","graphify-out"}
def scan(p):
    n=0; newest=0
    for root, dirs, files in os.walk(p):
        dirs[:] = [d for d in dirs if d not in SKIPD]
        for f in files:
            if f in ("STATUS.md",): continue
            try: m=os.path.getmtime(os.path.join(root,f))
            except OSError: continue
            n+=1; newest=max(newest,m)
    return n, dt.date.fromtimestamp(newest).isoformat() if newest else "-"
def first_line(p):
    for name in ("README.md","CLAUDE.md","AGENTS.md"):
        f=p/name
        if f.exists():
            for l in f.read_text(encoding="utf-8",errors="ignore").splitlines():
                l=l.strip("# ").strip()
                if l and not l.startswith(("@","<!--","---")) and len(l)>15: return l[:110]
    return ""
def stub(p):
    f=p/"docs/STATUS.md"
    if not f.exists(): return "noSTATUS"
    t=f.read_text(encoding="utf-8",errors="ignore")
    return "stub" if ("brought under git" in t and len(t.splitlines())<25) else "real"
reg=json.load(open(DEV/"project-triage/portfolio.json",encoding="utf-8"))
regn={}
for s in ("projects","ideas","inbox"):
    for it in reg.get(s,[]):
        if isinstance(it,dict):
            nm=it.get("name") or it.get("id") or ""
            regn[nm.lower()]=f"{s}:{it.get('status') or it.get('stage') or ''}"
for fam, ms in FAM.items():
    print(f"\n## {fam}")
    for m in ms:
        p=DEV/m
        if not p.exists(): print(f"  {m}: MISSING"); continue
        n,new=scan(p)
        print(f"  {m} | files={n} newest={new} | {stub(p)} | reg={regn.get(m.lower(),'-')} | {first_line(p)}")

