class TestOrganizationFields(unittest.TestCase):
    """Fields added 2026-10-03 so every DEV folder and Drive project can have a row."""

    def with_beta(self, **beta):
        data = minimal_registry()
        data["projects"].append(dict(data["projects"][0], name="Beta", rank=2, **beta))
        return data

    def test_new_lanes_are_accepted(self):
        for lane in ("system", "knowledge", "tool"):
            portfolio.validate(self.with_beta(lane=lane, status="paused"))

    def test_merged_and_archived_statuses_are_accepted(self):
        portfolio.validate(self.with_beta(status="merged", parent="Alpha"))
        portfolio.validate(self.with_beta(status="archived"))

    def test_parent_must_name_an_existing_project(self):
        with self.assertRaises(portfolio.RegistryError):
            portfolio.validate(self.with_beta(parent="Nope"))

    def test_project_cannot_be_its_own_parent(self):
        with self.assertRaises(portfolio.RegistryError):
            portfolio.validate(self.with_beta(parent="Beta"))

    def test_merged_requires_a_parent(self):
        with self.assertRaises(portfolio.RegistryError):
            portfolio.validate(self.with_beta(status="merged"))

    def test_drive_folder_must_be_a_string(self):
        portfolio.validate(self.with_beta(drive_folder="01_PROJECTS/_ACTIVE/2026-03-09_VALD_Release"))
        with self.assertRaises(portfolio.RegistryError):
            portfolio.validate(self.with_beta(drive_folder=["x"]))

    def test_merged_and_archived_rows_skip_the_rank_clash_check(self):
        # ranks only clash among active rows; retired rows keep whatever rank they had
        portfolio.validate(self.with_beta(rank=1, status="archived"))
