def main(argv: list[str] | None = None) -> int:
    script_dir = Path(__file__).resolve().parent
    registry_path = script_dir / "portfolio.json"
    dashboard_path = script_dir / "dashboard.html"
    pulse_path = script_dir / "pulse.md"

    parser = argparse.ArgumentParser(prog="render.py")
    parser.add_argument("--no-scan", action="store_true", help="skip DEV/ heuristics scan")
    args = parser.parse_args(argv)

    try:
        data = portfolio.load_registry(registry_path)
    except portfolio.RegistryError as e:
        print(f"[error] {e}", file=sys.stderr)
        return 2

    dev_root = Path.home() / "DEV"

    if args.no_scan:
        heur: dict[str, dict] = {}
    else:
        heur = scan_heuristics(dev_root)

    docs: dict[str, dict] = {}
    for p in data.get("projects", []):
        dev_folder = p.get("dev_folder") or ""
        if dev_folder:
            docs[dev_folder] = detect_docs(dev_root / dev_folder)

    today = datetime.date.today()
    vm = assemble(data, heur, today, docs=docs)

    dashboard_path.write_text(render_dashboard(vm), encoding="utf-8")
    pulse_path.write_text(render_pulse(vm), encoding="utf-8")

    project_count = len(data.get("projects", []))

