186	<div id="app"></div>
187	<div class="flash" id="flash"></div>
188	
189	<script>
190	const TOKEN = new URLSearchParams(location.search).get("token") || "";
191	const STAGES = ["idea","grilled","spec","planned","building","shipped"];
192	const STATUSES = ["active","paused","done","dropped"];
193	const ARCHIVED = new Set(["done","dropped"]);
194	let REG = null, lane = "job", openCard = null;
195	const drafts = new Map();          // inbox name -> {purpose?, next_action?} draft edits not yet promoted
196	
197	function applyDrafts(){
198	  (REG.inbox || []).forEach(r => {
199	    const d = drafts.get(r.name);
200	    if(d) Object.assign(r, d);
201	  });
202	}
203	
204	function flash(msg){
205	  const f = document.getElementById("flash");
206	  f.textContent = msg; f.style.display = "block";
207	  clearTimeout(flash.t); flash.t = setTimeout(()=>f.style.display="none", 5000);
208	}
209	async function api(path, opts = {}){
210	  const sep = path.includes("?") ? "&" : "?";
211	  const res = await fetch(path + sep + "token=" + encodeURIComponent(TOKEN), {
212	    headers: {"Content-Type":"application/json"}, ...opts
213	  });
214	  if(!res.ok){
215	    let msg = res.statusText;
216	    try { msg = (await res.json()).error || msg; } catch {}
217	    throw new Error(msg);
218	  }
219	  return res.json();
220	}
221	function showBlocked(msg){
222	  const app = document.getElementById("app");
223	  app.textContent = "";
224	  const p = document.createElement("p");
225	  p.className = "blocked";
226	  p.textContent = "Cannot load the board: " + msg;
227	  app.append(p);
228	}
229	async function load(){
230	  try {
231	    REG = await api("/api/registry");
232	    applyDrafts();
233	    render();
234	  } catch(e){
235	    flash(e.message);
236	    if(!REG) showBlocked(e.message);
237	  }
238	}
239	
240	// any failed write reloads from disk, so the board never shows a state that was not saved
241	async function write(path, payload, method = "POST"){
242	  let ok = true;
243	  try {
244	    const opts = {method};
245	    if(method !== "DELETE") opts.body = JSON.stringify(payload || {});
246	    await api(path, opts);
247	  } catch(e){
248	    ok = false;
249	    flash(e.message);
250	  }
251	  await load();          // load() handles its own errors, so a failed reload is never silent
252	  return ok;
253	}
254	
255	const idx = s => Math.max(0, STAGES.indexOf(s));
256	const live = l => REG.projects
257	  .filter(p => p.lane === l && !ARCHIVED.has(p.status))
258	  .sort((a,b) => (a.rank||1e6) - (b.rank||1e6));
259	
260	// Project names are one long word joined by underscores, so the browser has no break
261	// opportunity and cuts mid-syllable ("AT_Utilization_B / enchmarks"). Mark the joins
262	// with <wbr> instead. Built as nodes, not innerHTML — names stay untrusted text.
263	function nameNodes(name){
264	  const frag = document.createDocumentFragment();
265	  const parts = String(name).split("_");
266	  parts.forEach((seg, i) => {
267	    const last = i === parts.length - 1;
268	    frag.append(document.createTextNode(last ? seg : seg + "_"));
269	    if(!last) frag.append(document.createElement("wbr"));
270	  });
271	  return frag;
272	}
273	
274	const needsAction = rec =>
275	  (rec.status || "active") === "active" && !(rec.next_action || "").trim();
276	
277	let dragged = null;
278	function card(rec, from){
279	  const open = openCard === rec.name;
280	  const archived = ARCHIVED.has(rec.status);
281	  const d = document.createElement("div");
282	  d.className = "card" + (open ? " open" : "") + (archived ? " archived" : "")
283	              + (from === "board" && rec.rank === 1 ? " front" : "");
284	  d.dataset.name = rec.name;
285	  d.draggable = !open && !archived;
286	
287	  const row = document.createElement("div"); row.className = "nm";
288	  // Rank is a live-lane position, so an archived card has none to show — its stored
289	  // rank is the placeholder the archive op parks it at, never a real standing.
290	  if(from !== "inbox" && !archived){
291	    const rk = document.createElement("span"); rk.className = "rk";
292	    rk.textContent = rec.rank ?? "—";
293	    row.append(rk);
294	  }
295	  const h = document.createElement("h3");
296	  h.append(nameNodes(rec.name));
297	  row.append(h);
298	  d.append(row);
299	
300	  if(!open){
301	    const p = document.createElement("p");
302	    p.className = "purpose" + (rec.purpose ? "" : " none");
303	    p.textContent = rec.purpose || "No purpose yet";
304	    d.append(p);
305	  }
306	  if(from !== "inbox"){
307	    const s = document.createElement("div"); s.className = "stage";
308	    const leds = document.createElement("div"); leds.className = "leds";
309	    const reached = idx(rec.stage);
310	    STAGES.forEach((_, i) => {
311	      const led = document.createElement("i");
312	      if(i <= reached) led.className = "on";
313	      leds.append(led);
314	    });
315	    const lab = document.createElement("b");
316	    lab.textContent = `${rec.stage || "unstaged"} ${reached+1}/${STAGES.length}`;
317	    s.append(leds, lab);
318	
319	    // The pill rides the stage row, not the name row. Sharing a line with the title
320	    // cost it half its width and forced every name to two or three lines; the stage
321	    // row had the room to spare.
322	    const sel = document.createElement("select");
323	    const st = rec.status || "active";
324	    sel.className = "st st-" + st;
325	    STATUSES.forEach(v => {
326	      const o = document.createElement("option");
327	      o.value = v; o.textContent = v; o.selected = v === st;
328	      sel.append(o);
329	    });
330	    sel.onmousedown = e => e.stopPropagation();
331	    sel.onclick = e => e.stopPropagation();
332	    sel.onchange = e => {
333	      e.stopPropagation();
334	      write(`/api/project/${encodeURIComponent(rec.name)}`, {status: sel.value});
335	    };
336	    s.append(sel);
337	    d.append(s);
338	
339	    // Promotion is gate-free, so the gap is surfaced here instead of blocking the
340	    // drag. Same predicate render.py uses — active only, whitespace counts as
341	    // blank — so the board and the dashboard cannot disagree about it.
342	    if(needsAction(rec)){
343	      const f = document.createElement("div"); f.className = "needs";
344	      f.textContent = "⚠ Needs a next action";
345	      d.append(f);
346	    }
347	  }
348	  if(open) d.append(panel(rec, from));
349	
350	  d.onclick = () => { openCard = open ? null : rec.name; render(); };
351	  d.addEventListener("dragstart", e => {
352	    dragged = {rec, from};
353	    d.classList.add("dragging");
354	    e.dataTransfer.effectAllowed = "move";
355	    e.dataTransfer.setData("text/plain", rec.name);
356	  });
357	  d.addEventListener("dragend", () => { dragged = null; d.classList.remove("dragging"); });
358	  return d;
359	}
360	
361	function panel(rec, from){
362	  const p = document.createElement("div"); p.className = "panel";
363	  p.onclick = e => e.stopPropagation();
364	  p.onmousedown = e => e.stopPropagation();
365	
366	  if(from === "inbox"){
367	    const w = document.createElement("div"); w.className = "note";
368	    w.textContent = "Drag onto a stage column to promote, or onto Archive to retire it. "
369	                  + "Neither needs anything filled in first — a promoted project just wears "
370	                  + "a red flag until it has a next action.";
371	    p.append(w);
372	  }
373	  // The board shows one lane at a time and drops into the lane it is showing, so a
374	  // mislabeled project can only be moved from here.
375	  if(from !== "inbox"){
376	    const l = document.createElement("label"); l.textContent = "lane";
377	    const g = document.createElement("div"); g.className = "lanes";
378	    ["job","side"].forEach(v => {
379	      const b = document.createElement("button");
380	      b.className = "lanebtn" + (v === rec.lane ? " on" : "");
381	      b.textContent = v;
382	      b.disabled = v === rec.lane;
383	      b.onclick = async () => {
384	        if(await write(`/api/project/${encodeURIComponent(rec.name)}/lane`, {lane: v})){
385	          lane = v;          // follow the card to its new lane instead of losing it
386	          render();
387	        }
388	      };
389	      g.append(b);
390	    });
391	    p.append(l, g);
392	  }
393	
394	  const field = (key, label, tag) => {
395	    const l = document.createElement("label"); l.textContent = label;
396	    const el = document.createElement(tag);
397	    if(tag === "textarea") el.rows = 3;
398	    el.value = rec[key] || "";
399	    if(!el.value) el.classList.add("missing");
400	    el.oninput = () => {
401	      rec[key] = el.value;
402	      el.classList.toggle("missing", !el.value);
403	      if(from === "inbox"){
404	        const d = drafts.get(rec.name) || {};
405	        d[key] = el.value;
406	        drafts.set(rec.name, d);
407	      }
408	    };
409	    el.onchange = () => {
410	      if(from === "inbox") return;             // inbox edits are held until promotion
411	      write(`/api/project/${encodeURIComponent(rec.name)}`, {[key]: el.value});
412	    };
413	    p.append(l, el);
414	  };
415	  field("purpose", "purpose", "textarea");
416	  field("next_action", "next action", "input");
417	
418	  if(from !== "inbox"){
419	    const l = document.createElement("label"); l.textContent = "add update";
420	    const add = document.createElement("input");
421	    add.placeholder = "one line, then Enter";
422	    add.onkeydown = e => {
423	      if(e.key !== "Enter" || !add.value.trim()) return;
424	      write(`/api/project/${encodeURIComponent(rec.name)}`, {note: add.value.trim()});
425	    };
426	    p.append(l, add);
427	    (rec.updates || []).slice(0, 6).forEach(u => {
428	      const d = document.createElement("div"); d.className = "up";
429	      const b = document.createElement("b"); b.textContent = u.date + " ";
430	      d.append(b, document.createTextNode(u.note));
431	      p.append(d);
432	    });
433	    const del = document.createElement("button");
434	    del.className = "danger"; del.textContent = "Delete project";
435	    del.onclick = () => {
436	      if(confirm(`Delete "${rec.name}"? This rewrites portfolio.json.`))
437	        write(`/api/project/${encodeURIComponent(rec.name)}`, null, "DELETE");
438	    };
439	    p.append(del);
440	  }
441	  return p;
442	}
443	
444	function column(title, count, cls){
445	  const c = document.createElement("div"); c.className = "col " + (cls || "");
446	  const h = document.createElement("h2");
447	  const a = document.createElement("span"); a.textContent = title;
448	  const b = document.createElement("span"); b.className = "n"; b.textContent = count;
449	  h.append(a, b);
450	  const z = document.createElement("div"); z.className = "drop";
451	  c.append(h, z);
452	  return {col: c, zone: z};
453	}
454	
455	function emptyNote(zone, text){
456	  const e = document.createElement("p"); e.className = "empty"; e.textContent = text;
457	  zone.append(e);
458	}
459	
460	function dropTarget(colEl, zoneEl, stage){
461	  colEl.addEventListener("dragover", e => { e.preventDefault(); colEl.classList.add("over"); });
462	  colEl.addEventListener("dragleave", () => colEl.classList.remove("over"));
463	  colEl.addEventListener("drop", e => {
464	    e.preventDefault(); colEl.classList.remove("over");
465	    if(!dragged) return;
466	    const cards = [...zoneEl.querySelectorAll(".card")].filter(c => c.dataset.name !== dragged.rec.name);
467	    let position = cards.length;
468	    for(let i = 0; i < cards.length; i++){
469	      const r = cards[i].getBoundingClientRect();
470	      if(e.clientY < r.top + r.height/2){ position = i; break; }
471	    }
472	    const {rec, from} = dragged;
473	    if(from === "inbox"){
474	      write(`/api/inbox/${encodeURIComponent(rec.name)}/promote`,
475	            {lane, stage, position, purpose: rec.purpose || "", next_action: rec.next_action || ""})
476	        .then(ok => { if(ok) drafts.delete(rec.name); });
477	    } else {
478	      write("/api/move", {name: rec.name, lane, stage, position});
479	    }
480	  });
481	}
482	
483	// Archive is a drop target too, but it has no ordering: `position` is meaningless
484	// there, and /api/move would reject "archive" anyway — it is not a stage. So this
485	// is deliberately separate from dropTarget rather than a call with a fake stage.
486	function archiveTarget(colEl){
487	  colEl.addEventListener("dragover", e => { e.preventDefault(); colEl.classList.add("over"); });
488	  colEl.addEventListener("dragleave", () => colEl.classList.remove("over"));
