import datetime as dt
import unittest

import board_ops
import seven_day
import slate

TODAY = dt.date(2026, 10, 20)


def row(name, **kw):
    base = {"name": name, "lane": "side", "rank": 1, "status": "active", "purpose": "", "next_action": ""}
    base.update(kw)
    return base


def reg(*rows):
    return {"meta": {}, "ideas": [], "inbox": [], "projects": list(rows)}


class TestProved(unittest.TestCase):
    def test_needs_both_a_receiver_and_a_first_step(self):
        self.assertFalse(seven_day.proved(row("A", receiver="Joe")))
        self.assertFalse(seven_day.proved(row("A", first_step_done="2026-10-15")))
        self.assertTrue(seven_day.proved(row("A", receiver="Joe", first_step_done="2026-10-15")))

    def test_a_charter_counts_for_job_work(self):
        charter = {"receiver": "Kenny", "steps": [{"name": "Plan agreed", "due": "2026-10-10", "done": "2026-10-09"}]}
        self.assertTrue(seven_day.proved(row("A", lane="job", charter=charter)))
        charter["steps"][0]["done"] = None
        self.assertFalse(seven_day.proved(row("A", lane="job", charter=charter)))


class TestCheck(unittest.TestCase):
    def test_expired_after_seven_days_without_proof(self):
        r = seven_day.check(reg(row("Old", started="2026-10-12")), TODAY)
        self.assertEqual([(p["project"], p["level"]) for p in r], [("Old", "OVERDUE")])

    def test_warns_from_day_five(self):
        r = seven_day.check(reg(row("Mid", started="2026-10-15")), TODAY)
        self.assertEqual(r[0]["level"], "DUE")
        self.assertIn("2 days left", r[0]["message"])

    def test_quiet_before_day_five_and_for_exempt_lanes_and_grandfathered_rows(self):
        data = reg(row("New", started="2026-10-18"),
                   row("Kb", lane="knowledge", started="2026-10-01"),
                   row("Old", started="2026-10-01", seven_day_exempt=True),
                   row("Paused", status="paused", started="2026-10-01"),
                   row("Proved", started="2026-10-01", receiver="Joe", first_step_done="2026-10-05"))
        self.assertEqual(seven_day.check(data, TODAY), [])

    def test_slate_check_carries_the_countdown(self):
        data = reg(row("Old", started="2026-10-12"))
        data["meta"]["slate"] = {"cap": 5}
        problems = slate.check(data, TODAY)["problems"]
        self.assertTrue(any(p["project"] == "Old" and "7-day" in p["message"] for p in problems))


class TestApply(unittest.TestCase):
    def test_pauses_expired_rows_with_a_note(self):
        data = reg(row("Old", started="2026-10-12"), row("New", started="2026-10-18"))
        paused = seven_day.apply(data, TODAY)
        self.assertEqual(paused, ["Old"])
        old = data["projects"][0]
        self.assertEqual(old["status"], "paused")
        self.assertIn("7-day rule", old["updates"][0]["note"])
        self.assertEqual(data["projects"][1]["status"], "active")


class TestClockStarts(unittest.TestCase):
    def test_missing_start_dates_are_stamped_for_active_covered_rows(self):
        data = reg(row("A"), row("B", lane="system"), row("C", status="paused"))
        seven_day.stamp_started(data, TODAY)
        self.assertEqual(data["projects"][0]["started"], "2026-10-20")
        self.assertNotIn("started", data["projects"][1])
        self.assertNotIn("started", data["projects"][2])

    def test_reactivating_restarts_the_clock_and_drops_grandfathering(self):
        data = reg(row("A", status="paused", started="2026-01-01", seven_day_exempt=True))
        board_ops.patch_project(data, "A", status="active", today="2026-10-20")
        self.assertEqual(data["projects"][0]["started"], "2026-10-20")
        self.assertNotIn("seven_day_exempt", data["projects"][0])


if __name__ == "__main__":
    unittest.main()

